import{_ as i,o as t,c as a,a2 as e}from"./chunks/framework.hwbV7reR.js";const c=JSON.parse('{"title":"Участие в разработке","description":"","frontmatter":{},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md","lastUpdated":1791695486000}'),n={name:"contributing.md"};function r(h,s,p,l,d,o){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="участие-в-разработке" tabindex="-1">Участие в разработке <a class="header-anchor" href="#участие-в-разработке" aria-label="Permalink to &quot;Участие в разработке&quot;">​</a></h1><p>Начните с <a href="./architecture.html">архитектуры</a>, <a href="./lifecycle.html">гарантий жизненного цикла</a>, <a href="./compatibility.html">правил совместимости</a> и <a href="./api.html">контракта API</a>. Тесты не требуют настоящих серверов, соседнего закрытого репозитория или VPN-ключей.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements-dev.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-deps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check_contracts.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check_architecture.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mypy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span></code></pre></div><p>CI выполняет эти проверки на Python 3.12/Linux и собирает архив точного коммита. Ручная проверка на реальном узле — отдельный этап, не часть обычного pytest.</p><h2 id="где-менять-код" tabindex="-1">Где менять код <a class="header-anchor" href="#где-менять-код" aria-label="Permalink to &quot;Где менять код&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Задача</th><th>Место</th></tr></thead><tbody><tr><td>Модели входа/выхода</td><td><code>orchestrator/domain/contracts.py</code></td></tr><tr><td>HTTP-граница</td><td><code>orchestrator/interfaces/http/</code></td></tr><tr><td>Команды оператора</td><td><code>orchestrator/interfaces/cli/</code></td></tr><tr><td>Выдача и восстановление</td><td><code>orchestrator/application/</code></td></tr><tr><td>Протокольный драйвер</td><td><code>orchestrator/infrastructure/drivers/</code></td></tr><tr><td>Интерфейсы журналов</td><td><code>orchestrator/application/repository_ports.py</code></td></tr><tr><td>Хранение и транзакции</td><td><code>orchestrator/infrastructure/sqlite/</code></td></tr><tr><td>Модели таймаутов и конфигурации</td><td><code>orchestrator/config/</code></td></tr><tr><td>Загрузка конфигурации и секретов</td><td><code>orchestrator/infrastructure/settings.py</code>, <code>credentials.py</code></td></tr><tr><td>Сборка реализаций</td><td><code>orchestrator/bootstrap.py</code></td></tr></tbody></table><p>Корневые runtime/settings/assignments и другие короткие модули — совместимые импорты старых точек запуска. Новую реализацию добавляйте в соответствующий слой. Не удаляйте совместимость без описанного перехода.</p><p>Проверка импортов использует contracts/architecture.json. Новые запрещённые зависимости и устаревшие исключения блокируют CI. Список исключений не обновляется автоматически; сейчас он пуст. Mypy проверяет типы на границах слоёв и соответствие реализаций портам; область проверки явно задана в pyproject.toml.</p><h2 id="изменение-контракта" tabindex="-1">Изменение контракта <a class="header-anchor" href="#изменение-контракта" aria-label="Permalink to &quot;Изменение контракта&quot;">​</a></h2><p>Обновляйте код, машинную схему, публичные примеры и тесты вместе. <code>python scripts/export_openapi.py</code> пересобирает статическую OpenAPI для новых интеграций; <code>--check</code> проверяет, что артефакт актуален. <code>check_contracts.py</code> проверяет также прежнюю JSON Schema, каталог кодов и контрольные суммы fixture агента. Новый HTTP-код или другая семантика повтора требуют отдельного анализа совместимости.</p><p>Тестируйте наблюдаемое поведение: повтор после потери ответа, истечение срока, отзыв, перезапуск незавершённой операции. Не изменяйте pinned fixture агента только ради прохождения теста. Для нового протокола используйте <a href="./drivers.html">руководство</a>.</p><h2 id="pull-request" tabindex="-1">Pull request <a class="header-anchor" href="#pull-request" aria-label="Permalink to &quot;Pull request&quot;">​</a></h2><p>Опишите проблему, получившееся поведение, совместимость, миграции и проверки. Один PR должен иметь понятную цель. Для рефакторинга сначала зафиксируйте важное поведение тестом, затем меняйте реализацию. Не добавляйте биллинг, пользовательскую авторизацию или зависимости от админки сайта.</p><p>Документы размещаются в docs/public или docs/internal; README в корне — короткий вход в документацию. Реальные настройки, базы, ключи и конфигурации не коммитятся. Собственный код проекта распространяется по <a href="https://github.com/UndercoreCo/orchestrator/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT</a>. При добавлении стороннего кода сохраняйте сведения об авторстве и его лицензии.</p><h2 id="саит-документации" tabindex="-1">Сайт документации <a class="header-anchor" href="#саит-документации" aria-label="Permalink to &quot;Сайт документации&quot;">​</a></h2><p>Публичный сайт: <a href="https://undercoreco.github.io/orchestrator/" target="_blank" rel="noreferrer">https://undercoreco.github.io/orchestrator/</a>. VitePress читает только docs/public; docs/internal не входит в сборку сайта. Публичный GitHub-репозиторий остаётся публичным: исключение из сайта не закрывает доступ к уже опубликованным файлам репозитория.</p><p>Для редактирования используйте Node.js 24 и npm:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span></span></code></pre></div><p>Markdown остаётся единственным источником содержимого. Ссылки на код и машинные контракты ведут в GitHub, ссылки между руководствами — на страницы сайта. Поиск встроенный, локальный; внешняя поисковая служба не нужна.</p><p>GitHub Actions проверяет сборку в pull request. После изменения публичной документации в main автоматически публикуется только каталог .vitepress/dist. API, службы оркестратора и VPN-узлы этот workflow не разворачивает.</p>`,20)])])}const F=i(n,[["render",r]]);export{c as __pageData,F as default};
